arguments.command:
python3 - <<'PY'
from pathlib import Path
for p in sorted(Path('conf').glob('*.yaml')):
    lines = p.read_text().splitlines(keepends=True)
    new = []
    changed = False
    for line in lines:
        if line == 'log_level: debug\n':
            new.append('log_level: info\n')
            changed = True
        else:
            new.append(line)
    if changed:
        p.write_text(''.join(new))
        print(f'changed {p}')
    else:
        print(f'no change {p}')
PY
